/* MAHA shell repair. Existing handlers, native controls and permission nodes are retained. */
'use strict';
(()=>{function init(){let header=document.querySelector('body>header');const main=document.querySelector('main');const make=(tag,cls,text)=>{const e=document.createElement(tag);if(cls)e.className=cls;if(text)e.textContent=text;return e;};
if(!header&&main){header=make('header');const brand=make('a','brand');brand.href='index.html?view=home';brand.setAttribute('aria-label','MAHA home');brand.append(make('span','mark','m'),make('span','wordmark','MAHA'));const back=make('a','ui-trigger','Library');back.href='index.html?view=library';header.append(brand,back);document.body.prepend(header);}
function catalogState(){const file=location.pathname.split('/').pop();const view=document.documentElement.dataset.view||new URLSearchParams(location.search).get('view');document.body.classList.toggle('repair-catalog',['knowledge.html','music.html','archives.html','favorites.html'].includes(file)||((file==='index.html'||!file)&&view==='library'));if(view==='library'&&document.querySelector('#shelf-title'))document.querySelector('#shelf-title').textContent='Books';}catalogState();new MutationObserver(catalogState).observe(document.documentElement,{attributes:true,attributeFilter:['data-view']});
if(header?.querySelector('.brand')){document.body.classList.add('repair-shell');const account=make('details','repair-account'),summary=make('summary',null,'Profile'),panel=make('div','repair-account-panel');summary.setAttribute('aria-label','Account and appearance');account.append(summary,panel);header.append(account);const appearance=document.querySelector('.studio-appearance');if(appearance)panel.append(appearance);
function accountState(){const bar=document.querySelector('[data-maha-session-bar]');if(bar&&bar.parentElement!==panel)panel.prepend(bar);const slot=document.querySelector('#maha-session-slot');if(slot)slot.hidden=true;}
accountState();const obs=new MutationObserver(accountState);obs.observe(document.body,{childList:true,subtree:true});account.addEventListener('click',e=>{if(e.target.closest('a,button'))account.open=false;});document.addEventListener('click',e=>{if(!account.contains(e.target))account.open=false;});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&account.open){e.preventDefault();account.open=false;summary.focus();}},true);
// Existing appearance dialog normally restores focus to its trigger. Restore to
// the visible profile trigger when that trigger is inside the closed disclosure.
document.querySelector('#studio-appearance')?.addEventListener('close',()=>{if(!account.open)summary.focus();});}
const filterTrigger=document.querySelector('.ui-filter-trigger'),favoriteFilter=document.querySelector('.favorite-filter');if(filterTrigger&&favoriteFilter){const row=make('div','repair-controls-row');filterTrigger.before(row);row.append(filterTrigger,favoriteFilter);}
const albumDialog=document.querySelector('#album-dialog'),albumClose=document.querySelector('#album-close');if(albumDialog&&albumClose){const dismiss=make('div','repair-dialog-top');albumDialog.prepend(dismiss);dismiss.append(albumClose);}
// Native dialogs contain focus but do not lock the background document.
const syncDialogs=()=>document.documentElement.classList.toggle('repair-modal-open',!!document.querySelector('dialog[open]'));const modalObserver=new MutationObserver(syncDialogs);modalObserver.observe(document.body,{subtree:true,attributes:true,attributeFilter:['open'],childList:true});syncDialogs();
// Backdrop dismissal follows the same cancelable path as Escape. Existing
// uploading and other busy-state guards can veto it. Never treat an inside drag as outside.
let backdropStart=null;function outside(dialog,event){const r=dialog.getBoundingClientRect();return event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom;}
document.addEventListener('pointerdown',event=>{backdropStart=event.target instanceof HTMLDialogElement&&outside(event.target,event)?event.target:null;},true);
document.addEventListener('click',event=>{const dialog=event.target;if(!(dialog instanceof HTMLDialogElement)||!dialog.open||backdropStart!==dialog||!outside(dialog,event))return;backdropStart=null;if(typeof dialog.requestClose==='function')dialog.requestClose();else if(dialog.dispatchEvent(new Event('cancel',{cancelable:true})))dialog.close();});
// Native top-layer popovers escape the album's scroll clipping. Keep each
// panel inside the visible dialog bounds and choose the roomier side of its trigger.
function positionMenu(details){const menu=details.querySelector('.studio-menu-items'),dialog=details.closest('dialog'),anchor=details.querySelector('summary');if(!menu||!dialog||!anchor||!details.open)return;const a=anchor.getBoundingClientRect(),d=dialog.getBoundingClientRect(),gap=8,pad=12;const top=Math.max(pad,d.top+pad),bottom=Math.min(innerHeight-pad,d.bottom-pad),left=Math.max(pad,d.left+pad),right=Math.min(innerWidth-pad,d.right-pad);menu.style.maxHeight=Math.max(44,bottom-top)+'px';const width=Math.min(220,right-left);menu.style.width=width+'px';const height=menu.getBoundingClientRect().height,below=bottom-a.bottom-gap,above=a.top-gap-top;const useAbove=below<height&&above>below;const available=Math.max(44,useAbove?above:below);menu.style.maxHeight=Math.min(320,available)+'px';const actual=menu.getBoundingClientRect().height;menu.style.left=Math.max(left,Math.min(a.right-width,right-width))+'px';menu.style.top=Math.max(top,Math.min(useAbove?a.top-gap-actual:a.bottom+gap,bottom-actual))+'px';}
document.addEventListener('toggle',event=>{const details=event.target;if(!(details instanceof HTMLDetailsElement)||!details.classList.contains('studio-menu')||!details.closest('#album-dialog'))return;const menu=details.querySelector('.studio-menu-items');if(!menu)return;if(details.open){if(typeof menu.showPopover==='function'){menu.setAttribute('popover','manual');if(!menu.matches(':popover-open'))menu.showPopover();}positionMenu(details);}else if(typeof menu.hidePopover==='function'&&menu.matches(':popover-open'))menu.hidePopover();},true);
const albumMenus=document.querySelector('#album-dialog');if(albumMenus){albumMenus.addEventListener('scroll',()=>albumMenus.querySelectorAll('.studio-menu[open]').forEach(positionMenu),{passive:true});albumMenus.addEventListener('close',()=>albumMenus.querySelectorAll('.studio-menu-items').forEach(menu=>{if(menu.matches(':popover-open'))menu.hidePopover();}));}window.addEventListener('resize',()=>document.querySelectorAll('#album-dialog .studio-menu[open]').forEach(positionMenu));
if(main&&document.body.classList.contains('repair-catalog')){const labels={'music.html':'Music','knowledge.html':'Knowledge','archives.html':'Preserved web','favorites.html':'Favorites'};const file=location.pathname.split('/').pop();let title=document.querySelector('#shelf-title')||document.querySelector('.section-head h2');if(!title&&file==='favorites.html'){title=make('h1',null,'Favorites');main.prepend(title);}if(title){title.dataset.repairOriginal=title.textContent;const expected=labels[file]||'Books';title.textContent=expected;new MutationObserver(()=>{if(document.body.classList.contains('repair-catalog')&&title.textContent!==expected)title.textContent=expected;}).observe(title,{childList:true});}}
}if(document.readyState!=='complete')document.addEventListener('DOMContentLoaded',init,{once:true});else init();})();
